class AstroidTransform{scenes=[];scrollConfig={};el=null;constructor(el){this.el=el;this.scenes=JSON.parse(el.dataset.transformScenes);this.scrollConfig=el.dataset.transformScroll?JSON.parse(el.dataset.transformScroll):{};if(this.scrollConfig.scrub){this.scrollConfig.scrub=this.scrollConfig.scrub==="true"?true:parseFloat(this.scrollConfig.scrub)}}init(){const tl=gsap.timeline({paused:true});this.scenes.forEach(scene=>{if(scene.from){tl.fromTo(this.el,scene.from,scene.to||{})}else{tl.to(this.el,scene.to||{})}});ScrollTrigger.create({...{trigger:this.el,animation:tl},...this.scrollConfig})}}document.addEventListener("DOMContentLoaded",()=>{gsap.registerPlugin(ScrollTrigger);document.querySelectorAll("[data-transform-scenes]").forEach(el=>{const transform=new AstroidTransform(el);transform.init()})});